import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, Archive, ArrowDown, ArrowLeft, ArrowUp, AudioLines, Bot, Brain, Check, ChevronDown, ChevronLeft, ChevronRight, ChevronsUpDown, CircleHelp, Clock3, Code2, Command, Copy, DownloadCloud, File, FilePlus2, Folder, FolderOpen, Image as ImageIcon, Languages, LayoutGrid, LockKeyhole, Menu, MessageCircle, MessageSquare, MoreHorizontal, Paperclip, PanelLeftClose, Plus, Search, Settings2, ShieldCheck, Sparkles, SquarePen, RotateCcw, Trash2, UploadCloud, WandSparkles, X, Zap } from 'lucide-react';
