type Provider = { id:string; name:string; baseUrl:string; apiKey:string; models:string[] };
type Message = { id:string; role:'user'|'assistant'; content:string; thought?:string; files?:{name:string;type:string;data:string}[]; createdAt:number };
type Chat = { id:string; title:string; projectId?:string; updatedAt:number; messages:Message[] };
type Project = {id:string;name:string;color:string};
type Workspace = {providers:Provider[];selectedProvider:string;selectedModel:string;chats:Chat[];projects:Project[];activeProject:string;language:'en'|'fa';memory:boolean;fullAccess:boolean;effort:string;theme:'midnight'|'aurora'|'ember';accent:string;motion:boolean;autoUpdates:boolean};
const DEFAULT:Workspace={providers:[],selectedProvider:'',selectedModel:'',chats:[],projects:[],activeProject:'',language:'en',memory:true,fullAccess:false,effort:'medium',theme:'midnight',accent:'#e4aa72',motion:true,autoUpdates:true};
const isTauri=()=>Boolean((window as any).__TAURI_INTERNALS__);
const uid=()=>crypto.randomUUID();
const icons=[<Code2/>,<Folder/>,<Sparkles/>,<Bot/>];

async function loadWorkspace():Promise<Workspace>{
  try { if(isTauri()){const {invoke}=await import('@tauri-apps/api/core');const data=await invoke<Workspace|null>('load_workspace');if(data)return {...DEFAULT,...data};} else {const raw=localStorage.getItem('brba-workspace');if(raw)return {...DEFAULT,...JSON.parse(raw)};} } catch(e){console.warn('Could not load saved workspace',e)}
  return {...DEFAULT};
}
async function saveWorkspace(data:Workspace){try{if(isTauri()){const {invoke}=await import('@tauri-apps/api/core');await invoke('save_workspace',{workspace:data});}else localStorage.setItem('brba-workspace',JSON.stringify(data));}catch(e){console.error('Save failed',e)}}
function App(){
  const [ws,setWs]=useState<Workspace>(DEFAULT);const [ready,setReady]=useState(false);const [selectedChat,setSelectedChat]=useState('');const [query,setQuery]=useState('');const [input,setInput]=useState('');const [sending,setSending]=useState(false);const [settings,setSettings]=useState(false);const [settingsTab,setSettingsTab]=useState('providers');const [appVersion,setAppVersion]=useState('0.1.0');const [storagePath,setStoragePath]=useState('');const [searchOpen,setSearchOpen]=useState(false);const [newProvider,setNewProvider]=useState(false);const [providerDraft,setProviderDraft]=useState<Provider>({id:'',name:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',apiKey:'',models:[]});const [modelMenu,setModelMenu]=useState(false);const [effortMenu,setEffortMenu]=useState(false);const [projectMenu,setProjectMenu]=useState(false);const [projectModal,setProjectModal]=useState(false);const [projectName,setProjectName]=useState('');const [files,setFiles]=useState<{name:string;type:string;data:string}[]>([]);const [sidebarOpen,setSidebarOpen]=useState(true);const [toast,setToast]=useState('');const [activeTab,setActiveTab]=useState<'chat'|'work'>('work');const [fetching,setFetching]=useState(false);const [updateInfo,setUpdateInfo]=useState('');const fileRef=useRef<HTMLInputElement>(null);const importRef=useRef<HTMLInputElement>(null);const inputRef=useRef<HTMLTextAreaElement>(null);const stateRef=useRef(ws);
  useEffect(()=>{loadWorkspace().then(data=>{setWs(data);setReady(true)});},[]);
  useEffect(()=>{const access=(e:any)=>patch({fullAccess:e.detail});const model=(e:any)=>patch({selectedProvider:e.detail.provider,selectedModel:e.detail.model});const effort=(e:any)=>patch({effort:e.detail});const toastEvent=(e:any)=>notify(e.detail);window.addEventListener('agent-access',access);window.addEventListener('select-model',model);window.addEventListener('set-effort',effort);window.addEventListener('toast',toastEvent);return()=>{window.removeEventListener('agent-access',access);window.removeEventListener('select-model',model);window.removeEventListener('set-effort',effort);window.removeEventListener('toast',toastEvent)}},[]);
  useEffect(()=>{stateRef.current=ws;if(ready){const timer=window.setTimeout(()=>saveWorkspace(ws),350);return()=>window.clearTimeout(timer)}},[ws,ready]);
  const chat=ws.chats.find(c=>c.id===selectedChat);const provider=ws.providers.find(p=>p.id===ws.selectedProvider);const rtl=ws.language==='fa';
  const t=(en:string,fa:string)=>rtl?fa:en;
  useEffect(()=>{if(!isTauri())setStoragePath(t('Browser local storage','ذخیره‌سازی محلی مرورگر'));else import('@tauri-apps/api/path').then(({appDataDir})=>appDataDir().then(path=>setStoragePath(`${path}\\workspace.json`))).catch(()=>setStoragePath('%APPDATA%\\com.brbacoding.agent\\workspace.json'));if(isTauri())import('@tauri-apps/api/app').then(({getVersion})=>getVersion().then(setAppVersion)).catch(()=>{});},[rtl]);
  useEffect(()=>{
    if(!ready||!isTauri()||!import.meta.env.PROD)return;
    let active=true;let checking=false;
    const checkForUpdate=async()=>{
      if(checking||!active)return;checking=true;
      try{
        setUpdateInfo(t('Checking for updates…','در حال بررسی به‌روزرسانی…'));
        const {check}=await import('@tauri-apps/plugin-updater');
        const update=await check();
        if(!active)return;
        if(!update){setUpdateInfo(t('You’re up to date','برنامه به‌روز است'));window.setTimeout(()=>setUpdateInfo(''),4200);return;}
        setUpdateInfo(t(`Downloading version ${update.version}…`,`در حال دریافت نسخهٔ ${update.version}…`));
        let downloaded=0;let total=0;
        await update.downloadAndInstall(event=>{
          if(!active)return;
          if(event.event==='Started'){total=event.data.contentLength||0;setUpdateInfo(t(`Downloading ${update.version}…`,`در حال دریافت ${update.version}…`));}
          else if(event.event==='Progress'){downloaded+=event.data.chunkLength;if(total>0)setUpdateInfo(t(`Updating · ${Math.min(100,Math.round(downloaded/total*100))}%`,`به‌روزرسانی · ${Math.min(100,Math.round(downloaded/total*100))}٪`));}
          else if(event.event==='Finished')setUpdateInfo(t('Restarting to finish update…','برای تکمیل به‌روزرسانی، برنامه دوباره اجرا می‌شود…'));
        });
        const {relaunch}=await import('@tauri-apps/plugin-process');await relaunch();
      }catch(error){console.info('Automatic update check did not complete:',error);if(active){setUpdateInfo(t('Update check unavailable','بررسی به‌روزرسانی در دسترس نیست'));window.setTimeout(()=>setUpdateInfo(''),4200);}}
      finally{checking=false;}
    };
    const manual=()=>{void checkForUpdate()};window.addEventListener('check-app-updates',manual);
    let first=0;let interval=0;
    if(ws.autoUpdates){first=window.setTimeout(checkForUpdate,6500);interval=window.setInterval(checkForUpdate,6*60*60*1000);}
    return()=>{active=false;window.clearTimeout(first);window.clearInterval(interval);window.removeEventListener('check-app-updates',manual)};
  },[ready,rtl,ws.autoUpdates]);
  const sortedChats=useMemo(()=>[...ws.chats].sort((a,b)=>b.updatedAt-a.updatedAt),[ws.chats]);
  const filtered=sortedChats.filter(c=>c.title.toLowerCase().includes(query.toLowerCase())&&(!ws.activeProject||c.projectId===ws.activeProject));
  const activeProject=ws.projects.find(p=>p.id===ws.activeProject);
  const notify=(message:string)=>{setToast(message);setTimeout(()=>setToast(''),3200)};
  const patch=(updates:Partial<Workspace>)=>setWs(prev=>({...prev,...updates}));
  const showSettings=(tab='providers')=>{setSettingsTab(tab);setSettings(true)};
  async function exportWorkspace(){try{const blob=new Blob([JSON.stringify(ws,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='brba-workspace-backup.json';anchor.click();URL.revokeObjectURL(url);notify(t('Workspace backup exported. Keep it private; it contains API keys.','پشتیبان فضای کاری دانلود شد؛ فایل خصوصی است و کلیدهای API دارد.'))}catch{notify(t('Could not export workspace.','خروجی فضای کاری انجام نشد.'))}}
  async function importWorkspaceFile(file?:File){if(!file)return;try{const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.chats)||!Array.isArray(parsed.providers))throw new Error('Not a workspace backup');setWs({...DEFAULT,...parsed});setSelectedChat('');notify(t('Workspace backup imported.','پشتیبان فضای کاری وارد شد.'))}catch{notify(t('That file is not a valid workspace backup.','این فایل پشتیبان معتبر نیست.'))}}
  function clearChatHistory(){if(!window.confirm(t('Delete all chat history? This cannot be undone.','همه گفتگوها حذف شوند؟ این کار برگشت‌پذیر نیست.')))return;setWs(p=>({...p,chats:[]}));setSelectedChat('');notify(t('Chat history cleared.','تاریخچه گفتگو پاک شد.'))}
  const openChat=(id:string)=>{setSelectedChat(id);setActiveTab('chat')};
  function newChat(){setSelectedChat('');setInput('');setFiles([]);setActiveTab('work');inputRef.current?.focus()}
  function newConversation(first:Message){const id=uid();const title=first.content.trim().slice(0,42)||t('New chat','گفتگوی جدید');const next:Chat={id,title,projectId:ws.activeProject||undefined,updatedAt:Date.now(),messages:[first]};setWs(p=>({...p,chats:[next,...p.chats]}));setSelectedChat(id);return id}
  function updateMessage(chatId:string,messageId:string,changes:Partial<Message>){setWs(p=>({...p,chats:p.chats.map(c=>c.id===chatId?{...c,updatedAt:Date.now(),messages:c.messages.map(m=>m.id===messageId?{...m,...changes}:m)}:c)}))}
  function appendAssistant(chatId:string,messageId:string,piece:string){setWs(p=>({...p,chats:p.chats.map(c=>c.id===chatId?{...c,updatedAt:Date.now(),messages:c.messages.map(m=>m.id===messageId?{...m,content:m.content+piece,thought:''}:m)}:c)}))}
  function fileToBase64(file:File):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})}
  async function addFiles(list:FileList|null){if(!list)return;const selected=Array.from(list);const limit=isTauri()?8*1024*1024:2*1024*1024;const safe=selected.filter(f=>f.size<=limit);if(safe.length<selected.length)notify(t(`Files over ${limit/1024/1024} MB are skipped.`,`فایل‌های بزرگ‌تر از ${limit/1024/1024} مگابایت پیوست نمی‌شوند.`));const added=await Promise.all(safe.map(async f=>({name:f.name,type:f.type||'application/octet-stream',data:await fileToBase64(f)})));setFiles(p=>[...p,...added]);}
  async function refreshModels(target=provider){if(!target){notify(t('Add a provider in Settings first.','ابتدا در تنظیمات یک ارائه‌دهنده اضافه کنید.'));return}setFetching(true);try{let data:any;if(isTauri()){const {invoke}=await import('@tauri-apps/api/core');data=await invoke('fetch_models',{request:{baseUrl:target.baseUrl,apiKey:target.apiKey}})}else{const response=await fetch(`${target.baseUrl.replace(/\/$/,'')}/models`,{headers:{Authorization:`Bearer ${target.apiKey}`}});if(!response.ok)throw new Error(`Model request failed (${response.status}). Check URL/key and CORS.`);data=await response.json()}
    const models=(data.data||data.models||[]).map((m:any)=>typeof m==='string'?m:m.id).filter(Boolean).sort();if(!models.length)throw new Error('No models were returned by this provider.');setWs(p=>({...p,providers:p.providers.map(x=>x.id===target.id?{...x,models}:x),selectedProvider:target.id,selectedModel:p.selectedModel&&models.includes(p.selectedModel)?p.selectedModel:models[0]}));notify(`${models.length} ${t('models loaded','مدل بارگذاری شد')}`)
  }catch(e:any){notify(e?.toString?.().replace(/^Error: /,'')||'Could not fetch models')}finally{setFetching(false)}}
  async function send(){const text=input.trim();if((!text&&!files.length)||sending)return;if(!provider){setSettings(true);notify(t('Add an API provider in Settings to start chatting.','برای شروع گفتگو، یک ارائه‌دهنده API در تنظیمات اضافه کنید.'));return}if(!ws.selectedModel){setModelMenu(true);notify(t('Select a model first.','ابتدا یک مدل انتخاب کنید.'));return}
    const user:Message={id:uid(),role:'user',content:text,files,createdAt:Date.now()};const assistant:Message={id:uid(),role:'assistant',content:'',thought:'',createdAt:Date.now()};let cid=selectedChat;
    if(!cid||!ws.chats.some(c=>c.id===cid))cid=newConversation(user);else setWs(p=>({...p,chats:p.chats.map(c=>c.id===cid?{...c,updatedAt:Date.now(),messages:[...c.messages,user]}:c)}));
    setWs(p=>({...p,chats:p.chats.map(c=>c.id===cid?{...c,updatedAt:Date.now(),messages:[...c.messages,assistant]}:c)}));setInput('');setFiles([]);setSending(true);setActiveTab('chat');
    const current=stateRef.current;
    const history=(current.chats.find(c=>c.id===cid)?.messages||[]).concat(user);
    const kept=current.memory?history:history.slice(-6);
    const project=current.projects.find(p=>p.id===current.activeProject);
    const contextMessages=kept.map(m=>{
      const attachments=m.files||[];
      const textFiles=attachments.filter(f=>!f.type.startsWith('image/')&&(f.type.startsWith('text/')||['application/json','application/xml','application/javascript'].includes(f.type)||/\.(md|txt|csv|json|xml|js|jsx|ts|tsx|py|rs|html|css|yaml|yml|toml|sh)$/i.test(f.name))).map(f=>{
        try{return `${f.name}:\n${decodeURIComponent(escape(atob(f.data.split(',')[1]||'')))}`}catch{return `${f.name} (file attached)`}
      });
      const otherFiles=attachments.filter(f=>!f.type.startsWith('image/')&&!textFiles.some(x=>x.startsWith(`${f.name}:`))).map(f=>`Attached file: ${f.name} (not text-extracted)`);
      const text=[m.content,...textFiles,...otherFiles].filter(Boolean).join('\n\n');
      const content=attachments.some(f=>f.type.startsWith('image/'))?[{type:'text',text},...attachments.filter(f=>f.type.startsWith('image/')).map(f=>({type:'image_url',image_url:{url:f.data}}))]:text;
      return {role:m.role,content};
    });
    const all=[...(project?[{role:'system',content:`Project workspace: ${project.name}. Help with coding and software tasks. Do not claim to have performed local actions unless a tool actually did so.`}]:[]),...contextMessages];
    // An explicit work log gives the user visibility into what the agent is doing.
    updateMessage(cid,assistant.id,{thought:t('Thinking · preparing request','در حال فکر کردن · آماده‌سازی درخواست')});
    try{
      if(isTauri()){
        const {invoke}=await import('@tauri-apps/api/core');const {listen}=await import('@tauri-apps/api/event');
        const unlisten=await listen<any>('chat-stream',ev=>{if(ev.payload.request_id===assistant.id){const piece=ev.payload.text;appendAssistant(cid,assistant.id,piece)}});
        const done=await listen<any>('chat-stream-done',ev=>{if(ev.payload.request_id===assistant.id)done()});
        const result=await invoke('run_chat',{request:{baseUrl:provider.baseUrl,apiKey:provider.apiKey,model:current.selectedModel,messages:all,effort:current.effort,requestId:assistant.id}});unlisten();done();
      }else{
        const response=await fetch(`${provider.baseUrl.replace(/\/$/,'')}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${provider.apiKey}`},body:JSON.stringify({model:current.selectedModel,messages:all,stream:true,reasoning_effort:current.effort})});if(!response.ok){const msg=await response.text();throw new Error(`Request failed (${response.status}): ${msg.slice(0,240)}`)}
        if(!response.body)throw new Error('Streaming is not supported by this provider.');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';
        while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.startsWith('data:'))continue;const raw=line.slice(5).trim();if(raw==='[DONE]')continue;try{const payload=JSON.parse(raw);const delta=payload.choices?.[0]?.delta;const piece=delta?.content||'';if(piece){appendAssistant(cid,assistant.id,piece)}}catch{}}}
      }
      updateMessage(cid,assistant.id,{thought:''});
    }catch(e:any){updateMessage(cid,assistant.id,{content:`${t('Something went wrong:','خطایی رخ داد:')} ${e?.toString?.().replace(/^Error: /,'')||'Unknown error'}`,thought:''})}finally{setSending(false)}
  }
  function saveProvider(){const p={...providerDraft,id:providerDraft.id||uid(),models:providerDraft.models||[]};setWs(prev=>({...prev,providers:[...prev.providers.filter(x=>x.id!==p.id),p],selectedProvider:p.id,selectedModel:p.models[0]||''}));setNewProvider(false);setProviderDraft({id:'',name:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',apiKey:'',models:[]});setTimeout(()=>refreshModels(p),150)}
  function addProject(){if(!projectName.trim())return;const project={id:uid(),name:projectName.trim(),color:['#d7995d','#7b9ce4','#a47ce2','#6abd9b'][ws.projects.length%4]};setWs(p=>({...p,projects:[...p.projects,project],activeProject:project.id}));setProjectName('');setProjectModal(false)}
  function deleteChat(id:string){setWs(p=>({...p,chats:p.chats.filter(c=>c.id!==id)}));if(selectedChat===id)setSelectedChat('')}
  function onKey(e:React.KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}
  function requestUpdateCheck(){if(!isTauri()||!import.meta.env.PROD){notify(t('Update checks are available in the installed Windows release.','بررسی به‌روزرسانی در نسخهٔ نصب‌شدهٔ ویندوز فعال است.'));return}setUpdateInfo(t('Checking for updates…','در حال بررسی به‌روزرسانی…'));window.dispatchEvent(new Event('check-app-updates'))}
  const settingsNav=[['general',Settings2,t('General','عمومی')],['providers',Zap,t('Providers & models','ارائه‌دهنده و مدل')],['appearance',Sparkles,t('Appearance','ظاهر')],['memory',Brain,t('Memory','حافظه')],['agent',ShieldCheck,t('Agent access','دسترسی عامل')],['updates',ArrowDown,t('Updates','به‌روزرسانی')],['storage',Folder,t('Data & privacy','داده و حریم خصوصی')],['about',CircleHelp,t('About','درباره')]] as const;
  const settingsContent=<>
    {settingsTab==='general'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">WORKSPACE CONTROL</span><h3>{t('General preferences','تنظیمات عمومی')}</h3><p>{t('Tune the way Br Ba Coding Agent looks and works for you.','نحوهٔ نمایش و عملکرد برنامه را مطابق سلیقه‌ات تنظیم کن.')}</p></div></div><div className="settings-hero-card"><div className="settings-hero-mark">BB<i/></div><div><span className="eyebrow">YOUR WORKSPACE</span><h3>Br Ba Coding Agent</h3><p>{provider?`${provider.name} · ${ws.selectedModel||t('Choose a model','انتخاب مدل')}`:t('No AI provider connected yet','هنوز ارائه‌دهنده‌ای وصل نشده')}</p></div><div className="workspace-pulse"><i/>{provider?t('Connected','متصل'):t('Setup needed','نیاز به راه‌اندازی')}</div></div><div className="settings-section-title">{t('Interface language','زبان رابط کاربری')}</div><div className="choice-grid two"><button className={`choice-card ${!rtl?'chosen':''}`} onClick={()=>patch({language:'en'})}><span className="choice-symbol">EN</span><span><b>English</b><small>{t('Default language','زبان پیش‌فرض')}</small></span>{!rtl&&<Check size={16}/>}</button><button className={`choice-card ${rtl?'chosen':''}`} onClick={()=>patch({language:'fa'})}><span className="choice-symbol fa-symbol">فا</span><span><b>فارسی</b><small>Persian · راست‌چین</small></span>{rtl&&<Check size={16}/>}</button></div><div className="settings-section-title">{t('Workspace behavior','رفتار فضای کاری')}</div><div className="setting-row"><div className="setting-row-icon"><FolderOpen size={17}/></div><div className="setting-row-copy"><b>{t('Default project','پروژهٔ پیش‌فرض')}</b><small>{activeProject?.name||t('No project selected','پروژه‌ای انتخاب نشده')}</small></div><button className="outline small" onClick={()=>{setSettings(false);setProjectMenu(true)}}>{t('Choose','انتخاب')}</button></div></div>}
    {settingsTab==='providers'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">AI CONNECTIONS</span><h3>{t('Providers & models','ارائه‌دهنده‌ها و مدل‌ها')}</h3><p>{t('Connect multiple OpenAI-compatible APIs. Keys stay on this device.','چند API سازگار را متصل کن. کلیدها فقط روی همین دستگاه می‌مانند.')}</p></div><button className="primary small" onClick={()=>{setProviderDraft({id:'',name:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',apiKey:'',models:[]});setNewProvider(true)}}><Plus size={15}/>{t('Add provider','افزودن ارائه‌دهنده')}</button></div>{ws.providers.map(p=><div className="provider-card" key={p.id}><div className="provider-icon"><Activity size={17}/></div><div className="provider-info"><b>{p.name}</b><span>{p.baseUrl}</span><small>{p.models.length?`${p.models.length} ${t('models','مدل')}`:t('Models not loaded','مدل‌ها بارگذاری نشده‌اند')}</small></div><div className="provider-actions"><button className="outline small" onClick={()=>refreshModels(p)} disabled={fetching}><ArrowDown size={14}/>{fetching?t('Loading…','در حال دریافت…'):t('Fetch models','دریافت مدل‌ها')}</button><button className="icon-button" title={t('Edit provider','ویرایش')} onClick={()=>{setProviderDraft({...p});setNewProvider(true)}}><SquarePen size={14}/></button><button className="icon-button" title={t('Remove provider','حذف')} onClick={()=>setWs(s=>({...s,providers:s.providers.filter(x=>x.id!==p.id),selectedProvider:s.selectedProvider===p.id?'':s.selectedProvider,selectedModel:s.selectedProvider===p.id?'':s.selectedModel}))}><Trash2 size={15}/></button></div></div>)}{!ws.providers.length&&!newProvider&&<div className="no-providers"><div className="provider-icon"><Zap size={18}/></div><b>{t('Your AI workspace starts here','فضای هوش مصنوعی‌ات را وصل کن')}</b><span>{t('Add an API key to discover and choose the models available to you.','کلید API را اضافه کن تا مدل‌های در دسترس نمایش داده شوند.')}</span><button className="primary small" onClick={()=>{setProviderDraft({id:'',name:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',apiKey:'',models:[]});setNewProvider(true)}}><Plus size={14}/>{t('Connect provider','اتصال ارائه‌دهنده')}</button></div>}{newProvider&&<div className="provider-form"><div className="form-head"><b>{providerDraft.id?t('Edit provider','ویرایش ارائه‌دهنده'):t('Connect a provider','اتصال ارائه‌دهنده')}</b><button onClick={()=>setNewProvider(false)}><X size={16}/></button></div><label>{t('Provider name','نام ارائه‌دهنده')}<input value={providerDraft.name} onChange={e=>setProviderDraft({...providerDraft,name:e.target.value})} placeholder="OpenAI, OpenRouter, local gateway…"/></label><label>Base URL<input value={providerDraft.baseUrl} onChange={e=>setProviderDraft({...providerDraft,baseUrl:e.target.value})} placeholder="https://api.example.com/v1" dir="ltr"/></label><label>API key<input type="password" value={providerDraft.apiKey} onChange={e=>setProviderDraft({...providerDraft,apiKey:e.target.value})} placeholder="sk-…" dir="ltr" autoComplete="new-password"/></label><div className="form-note"><LockKeyhole size={13}/>{t('Saved in your local workspace file. Never share a backup containing keys.','در فایل محلی فضای کاری ذخیره می‌شود؛ فایل پشتیبانِ دارای کلید را به اشتراک نگذار.')}</div><div className="form-actions"><button className="outline small" onClick={()=>setNewProvider(false)}>{t('Cancel','لغو')}</button><button className="primary small" disabled={!providerDraft.baseUrl||!providerDraft.apiKey||!providerDraft.name} onClick={saveProvider}><Check size={14}/>{providerDraft.id?t('Save changes','ذخیره تغییرات'):t('Save & fetch models','ذخیره و دریافت مدل‌ها')}</button></div></div>}<div className="privacy-note"><ShieldCheck size={17}/><div><b>{t('Private by default','خصوصی به‌صورت پیش‌فرض')}</b><span>{t('Prompts and attachments are sent directly to the provider you choose.','پیام‌ها و فایل‌ها فقط به ارائه‌دهنده‌ای که انتخاب می‌کنی ارسال می‌شوند.')}</span></div></div></div>}
    {settingsTab==='appearance'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">MAKE IT YOURS</span><h3>{t('Appearance & motion','ظاهر و انیمیشن')}</h3><p>{t('Choose a color atmosphere and tune the motion intensity.','فضای رنگی و میزان حرکت رابط را انتخاب کن.')}</p></div></div><div className="settings-section-title">{t('Color atmosphere','فضای رنگی')}</div><div className="theme-grid">{[['midnight',t('Midnight','نیمه‌شب'),'#11141d','#e4aa72'],['aurora',t('Aurora','شفق قطبی'),'#101927','#8bafff'],['ember',t('Ember','اخگری'),'#1b1517','#f18c71']].map(([id,label,bg,accent])=><button key={id} className={`theme-card theme-preview-${id} ${ws.theme===id?'chosen':''}`} onClick={()=>patch({theme:id as Workspace['theme'],accent:accent as string})}><div className="theme-preview"><span/><i/><b/></div><span className="theme-label">{label}</span>{ws.theme===id&&<span className="theme-check"><Check size={12}/></span>}</button>)}</div><div className="settings-section-title">{t('Accent color','رنگ تأکیدی')}</div><div className="accent-row">{[['#e4aa72','Amber'],['#88aaff','Blue'],['#78c9aa','Mint'],['#c18cff','Violet'],['#f0809c','Rose']].map(([color,label])=><button key={color} title={label} className={`accent-swatch ${ws.accent===color?'selected':''}`} style={{'--swatch':color} as React.CSSProperties} onClick={()=>patch({accent:color})}><Check size={14}/></button>)}</div><div className="setting-row"><div className="setting-row-icon"><Sparkles size={17}/></div><div className="setting-row-copy"><b>{t('Interface animations','انیمیشن‌های رابط')}</b><small>{t('Ambient glow, transitions and motion details','نورپردازی و حرکت‌های ظریف رابط')}</small></div><button className={`toggle ${ws.motion?'checked':''}`} onClick={()=>patch({motion:!ws.motion})} aria-label="Toggle animations"/></div><div className="live-preview-card"><div className="preview-window"><div className="preview-window-top"><i/><i/><i/></div><div className="preview-orbit"><span>BB</span><b/></div><div className="preview-lines"><i/><i/><i/></div><div className="preview-input"><span>{t('Ask anything…','هر چیزی بپرس…')}</span><b>↑</b></div></div><div><span className="eyebrow">LIVE PREVIEW</span><b>{t('A little more alive.','کمی زنده‌تر.')}</b><small>{t('Your changes apply instantly throughout the workspace.','تغییرات همین حالا در تمام برنامه اعمال می‌شوند.')}</small></div></div></div>}
    {settingsTab==='memory'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">CONTEXT CONTROL</span><h3>{t('Memory & context','حافظه و زمینه')}</h3><p>{t('Choose how much of the current conversation is sent with each request.','تعیین کن چه مقدار از گفتگو همراه هر درخواست ارسال شود.')}</p></div></div><div className="memory-feature-card"><div className="memory-visual"><Brain size={24}/><i/><i/><i/></div><div className="memory-copy"><b>{t('Conversation memory','حافظهٔ گفتگو')}</b><p>{t('Keep earlier messages available so the model can follow the thread. This stays on your device until you send a request.','پیام‌های قبلی را برای حفظ پیوستگی گفتگو در درخواست‌ها نگه دار. تاریخچه روی دستگاهت می‌ماند.')}</p></div><button className={`toggle large ${ws.memory?'checked':''}`} onClick={()=>patch({memory:!ws.memory})} aria-label="Toggle memory"/></div><div className="memory-stats"><div><span>{t('Saved conversations','گفتگوهای ذخیره‌شده')}</span><b>{ws.chats.length}</b></div><div><span>{t('Messages on this device','پیام‌های این دستگاه')}</span><b>{ws.chats.reduce((sum,c)=>sum+c.messages.length,0)}</b></div></div><div className="context-choice"><div className="choice-radio">{ws.memory&&<i/>}</div><div><b>{t('Full conversation','کل گفتگو')}</b><small>{t('Send the complete chat history for richer context.','ارسال تمام تاریخچه برای زمینهٔ بیشتر.')}</small></div><span className="context-tag">{t('Recommended','پیشنهادی')}</span></div><div className="context-choice"><div className="choice-radio">{!ws.memory&&<i/>}</div><div><b>{t('Recent messages only','فقط پیام‌های اخیر')}</b><small>{t('Limit each request to the latest six messages.','در هر درخواست فقط شش پیام آخر ارسال شود.')}</small></div></div><button className="outline small context-select" onClick={()=>patch({memory:!ws.memory})}>{ws.memory?t('Use recent messages only','فقط پیام‌های اخیر'):t('Use full conversation','استفاده از کل گفتگو')}</button><div className="inline-note"><LockKeyhole size={15}/>{t('No separate cloud memory is created. Requests are sent to your selected provider.','حافظهٔ ابری جداگانه ساخته نمی‌شود؛ درخواست‌ها به ارائه‌دهندهٔ انتخابی ارسال می‌شوند.')}</div></div>}
    {settingsTab==='agent'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">SAFETY PREFERENCES</span><h3>{t('Agent access','دسترسی عامل')}</h3><p>{t('Control the permission preference shown in the chat composer.','ترجیح دسترسی که در کادر گفتگو نمایش داده می‌شود را تنظیم کن.')}</p></div></div><div className="permission-card"><div className="permission-icon"><ShieldCheck size={22}/></div><div><b>{t('Ask before actions','پرسش پیش از اقدام')}</b><p>{t('Safer mode. The app will ask before supported actions.','حالت امن‌تر؛ پیش از اقدام‌های پشتیبانی‌شده تأیید می‌گیرد.')}</p></div><button className={`toggle ${!ws.fullAccess?'checked':''}`} onClick={()=>patch({fullAccess:false})}/></div><div className="permission-card"><div className="permission-icon full"><Zap size={21}/></div><div><b>{t('Full access','دسترسی کامل')}</b><p>{t('Preference only for now. This build does not execute local tools or commands.','فعلاً فقط یک ترجیح نمایشی است؛ این نسخه ابزار یا فرمان محلی اجرا نمی‌کند.')}</p></div><button className={`toggle ${ws.fullAccess?'checked':''}`} onClick={()=>patch({fullAccess:true})}/></div><div className="warning-panel"><CircleHelp size={16}/><span>{t('Never send untrusted code or secrets to a model. Provider requests leave this device.','کد ناشناس یا رمزها را برای مدل ارسال نکن؛ درخواست‌ها به ارائه‌دهندهٔ انتخابی فرستاده می‌شوند.')}</span></div></div>}
    {settingsTab==='updates'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">STAY CURRENT</span><h3>{t('Updates','به‌روزرسانی‌ها')}</h3><p>{t('Get the newest Br Ba Coding Agent improvements.','تازه‌ترین بهبودهای Br Ba Coding Agent را دریافت کن.')}</p></div></div><div className="update-hero"><div className="update-emblem"><span/><ArrowDown size={24}/></div><div><span className="eyebrow">BR BA CODING AGENT</span><h3>{t('You’re on version','نسخهٔ فعلی')} {appVersion}</h3><p>{updateInfo||t('Updates are checked at launch and every six hours.','هنگام اجرا و هر شش ساعت به‌روزرسانی بررسی می‌شود.')}</p></div></div><div className="setting-row"><div className="setting-row-icon"><RotateCcw size={17}/></div><div className="setting-row-copy"><b>{t('Automatic updates','به‌روزرسانی خودکار')}</b><small>{t('Download, install and restart when a signed update is ready.','با آماده‌شدن نسخهٔ امضاشده، دانلود و نصب و راه‌اندازی مجدد شود.')}</small></div><button className={`toggle ${ws.autoUpdates?'checked':''}`} onClick={()=>patch({autoUpdates:!ws.autoUpdates})} aria-label="Toggle automatic updates"/></div><div className="update-actions"><button className="primary" onClick={requestUpdateCheck}><ArrowDown size={15}/>{t('Check for updates now','بررسی به‌روزرسانی')}</button><a className="outline small" href="https://github.com/Manixpcshot/BrBaCoding/releases/latest" target="_blank" rel="noreferrer">{t('View releases','مشاهده نسخه‌ها')}<ChevronRight size={14}/></a></div><div className="inline-note"><ShieldCheck size={15}/>{t('Updates are verified with a signing key before installation. Automatic update packages require release signing to be configured.','پیش از نصب، امضای دیجیتال بررسی می‌شود؛ بسته‌های به‌روزرسانی خودکار به کلید انتشار نیاز دارند.')}</div></div>}
    {settingsTab==='storage'&&<div className="settings-page animate-page"><div className="settings-title-row"><div><span className="eyebrow">LOCAL DATA</span><h3>{t('Data & privacy','داده و حریم خصوصی')}</h3><p>{t('Your workspace belongs to this device. Export a backup or clear data.','فضای کاری متعلق به همین دستگاه است؛ پشتیبان بگیر یا داده‌ها را پاک کن.')}</p></div></div><div className="storage-location"><div className="storage-icon"><FolderOpen size={20}/></div><div><span className="eyebrow">{t('WORKSPACE FILE','فایل فضای کاری')}</span><b>{storagePath||t('Loading location…','در حال دریافت مسیر…')}</b><small>{t('Contains conversations, provider settings and API keys. Keep backups private.','شامل گفتگوها، تنظیمات ارائه‌دهنده و کلیدهای API است؛ پشتیبان را خصوصی نگه دار.')}</small></div></div><div className="memory-stats"><div><span>{t('Conversations','گفتگوها')}</span><b>{ws.chats.length}</b></div><div><span>{t('Providers','ارائه‌دهنده‌ها')}</span><b>{ws.providers.length}</b></div><div><span>{t('Projects','پروژه‌ها')}</span><b>{ws.projects.length}</b></div></div><div className="settings-section-title">{t('Backup & restore','پشتیبان‌گیری و بازیابی')}</div><div className="storage-actions"><button className="outline" onClick={exportWorkspace}><DownloadCloud size={16}/>{t('Export backup','گرفتن پشتیبان')}</button><button className="outline" onClick={()=>importRef.current?.click()}><UploadCloud size={16}/>{t('Import backup','بازیابی پشتیبان')}</button><input ref={importRef} type="file" hidden accept="application/json,.json" onChange={e=>{void importWorkspaceFile(e.target.files?.[0]);e.currentTarget.value=''}}/></div><div className="settings-section-title danger-heading">{t('Danger zone','ناحیهٔ پرخطر')}</div><div className="setting-row danger-row"><div className="setting-row-icon"><Trash2 size={17}/></div><div className="setting-row-copy"><b>{t('Delete all conversations','حذف همه گفتگوها')}</b><small>{t('This cannot be undone. Provider settings will remain.','این کار برگشت‌پذیر نیست؛ تنظیمات ارائه‌دهنده باقی می‌ماند.')}</small></div><button className="danger-button" onClick={clearChatHistory}>{t('Clear history','پاک‌کردن')}</button></div></div>}
    {settingsTab==='about'&&<div className="settings-page animate-page about-page"><div className="about-brand"><div className="about-icon">BB<i/></div><span className="eyebrow">YOUR PRIVATE AI WORKSPACE</span><h2>Br Ba Coding Agent</h2><p>{t('A focused home for ideas, code and conversation.','فضایی متمرکز برای ایده‌ها، کد و گفتگو.')}</p><span className="version-pill">{t('VERSION','نسخه')} {appVersion}</span></div><div className="about-details"><div><span>{t('Built with','ساخته‌شده با')}</span><b>Rust · Tauri · React</b></div><div><span>{t('Workspace mode','حالت فضای کاری')}</span><b>{t('Local-first','اولویت با ذخیره محلی')}</b></div><div><span>{t('Language','زبان')}</span><b>{rtl?'فارسی':'English'}</b></div></div><a className="about-release-link" href="https://github.com/Manixpcshot/BrBaCoding/releases/latest" target="_blank" rel="noreferrer">{t('Open project releases','مشاهده نسخه‌های برنامه')}<ChevronRight size={15}/></a></div>}
  </>;
  return <div className={`app theme-${ws.theme} ${rtl?'rtl':''} ${ws.motion?'':'no-motion'}`} style={{'--user-accent':ws.accent} as React.CSSProperties}>
    {sidebarOpen&&<aside className="sidebar">
      <div className="side-top"><button className="brandmark" aria-label="Home" onClick={newChat}><span>BB</span></button><button className="side-icon" title="Collapse sidebar" onClick={()=>setSidebarOpen(false)}><PanelLeftClose size={17}/></button></div>
      <div className="workspace-label"><span className="brand-name">Br Ba <b>Coding Agent</b></span><button className="tiny-chevron"><ChevronDown size={14}/></button></div>
      <button className="new-chat" onClick={newChat}><SquarePen size={16}/><span>{t('New chat','گفتگوی جدید')}</span><kbd>⌘ K</kbd></button>
      <div className="side-actions"><button onClick={()=>setSearchOpen(!searchOpen)}><Search size={15}/>{t('Search chats','جستجوی گفتگو')}</button><button onClick={()=>setSettings(true)}><Clock3 size={15}/>{t('Settings','تنظیمات')}</button></div>{searchOpen&&<input className="sidebar-search" autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder={t('Search your chats…','جستجوی گفتگوها…')}/>} 
      <div className="side-scroll">
        <div className="section-title">{t('Projects','پروژه‌ها')}<button title="New project" onClick={()=>setProjectModal(true)}><Plus size={14}/></button></div>
        {ws.projects.map((p,i)=><div key={p.id} className={`project-row ${ws.activeProject===p.id?'selected':''}`}><button className="project-main" onClick={()=>patch({activeProject:ws.activeProject===p.id?'':p.id})}><span className="project-dot" style={{background:p.color}}>{icons[i%icons.length]}</span><span>{p.name}</span></button><button className="dots" onClick={()=>setWs(s=>({...s,projects:s.projects.filter(x=>x.id!==p.id),activeProject:s.activeProject===p.id?'':s.activeProject}))}><MoreHorizontal size={15}/></button></div>)}
        <button className="project-create" onClick={()=>setProjectModal(true)}><Plus size={14}/>{t('Create project','ساخت پروژه')}</button>
        <div className="section-title recent-title">{t('Recent','اخیر')}<button onClick={()=>{setQuery('');setSearchOpen(false)}}><MoreHorizontal size={15}/></button></div>
        {!filtered.length&&<div className="empty-history">{query?t('No matching chats','گفتگویی پیدا نشد'):t('Your chats will show up here.','گفتگوهای شما اینجا نمایش داده می‌شوند.')}</div>}
        {filtered.map(c=><div className={`history-row ${selectedChat===c.id?'active':''}`} key={c.id}><button className="history-title" onClick={()=>openChat(c.id)}>{c.title}</button><button className="dots" title="Delete chat" onClick={()=>deleteChat(c.id)}><MoreHorizontal size={15}/></button></div>)}
      </div>
      <div className="profile"><div className="avatar">BB</div><div className="profile-text"><b>Br Ba Workspace</b><small>{provider?.name||t('Set up your AI provider','ارائه‌دهنده را تنظیم کنید')}</small></div><button className="dots" onClick={()=>setSettings(true)}><MoreHorizontal size={16}/></button></div>
    </aside>}
    <main className="main">
      <header className="topbar">{!sidebarOpen&&<button className="topbar-icon" onClick={()=>setSidebarOpen(true)}><Menu size={17}/></button>}<div className="topbar-left"><button className="project-pill" onClick={()=>setProjectMenu(!projectMenu)}><FolderOpen size={15}/>{activeProject?.name||t('Workspace','فضای کاری')}<ChevronDown size={13}/></button>{projectMenu&&<div className="floating-menu project-menu"><button onClick={()=>{patch({activeProject:''});setProjectMenu(false)}}><LayoutGrid size={15}/>{t('All chats','همه گفتگوها')}</button>{ws.projects.map(p=><button key={p.id} onClick={()=>{patch({activeProject:p.id});setProjectMenu(false)}}><span className="project-dot" style={{background:p.color}}></span>{p.name}</button>)}<button onClick={()=>{setProjectMenu(false);setProjectModal(true)}}><Plus size={14}/>{t('New project','پروژه جدید')}</button></div>}</div>
        <div className="tab-switch"><button className={activeTab==='chat'?'on':''} onClick={()=>setActiveTab('chat')}>{t('Chat','چت')}</button><button className={activeTab==='work'?'on':''} onClick={()=>setActiveTab('work')}>{t('Work','کار')}</button></div><div className="topbar-right">{updateInfo&&<div className="update-status"><span className="update-spinner"/><span>{updateInfo}</span></div>}<button className="topbar-icon" title="Language" onClick={()=>patch({language:rtl?'en':'fa'})}><Languages size={16}/></button><button className="topbar-icon" title="Settings" onClick={()=>setSettings(true)}><Settings2 size={16}/></button><div className="mini-avatar">BB</div></div>
      </header>
      {chat&&activeTab==='chat'?<section className="conversation"><div className="conversation-head"><button className="back-btn" onClick={newChat}><ArrowLeft size={16}/></button><span>{chat.title}</span><button className="topbar-icon" onClick={()=>notify(t('Chat saved on this device','گفتگو روی این دستگاه ذخیره شد'))}><MoreHorizontal size={17}/></button></div><div className="messages">{chat.messages.map(m=><div className={`message ${m.role}`} key={m.id}>{m.role==='assistant'?<div className="assistant-avatar"><Sparkles size={15}/></div>:null}<div className="message-content">{m.thought&&<div className="think-line"><Brain size={14}/><span>{m.thought}</span><span className="thinking-dots"><i/><i/><i/></span></div>}{m.content&&<div className="message-text">{m.content}</div>}{m.files&&m.files.length>0&&<div className="attachment-list">{m.files.map((f,i)=><div className="attachment" key={i}>{f.type.startsWith('image/')?<img src={f.data} alt={f.name}/>:<File size={16}/>}<span>{f.name}</span></div>)}</div>}{m.role==='assistant'&&m.content&&!sending&&<div className="message-tools"><button onClick={()=>{navigator.clipboard?.writeText(m.content);notify(t('Copied','کپی شد'))}}><Copy size={14}/></button><button onClick={()=>notify(t('Saved to your local workspace','در فضای کاری ذخیره شد'))}><Archive size={14}/></button></div>}</div></div>)}</div><div className="chat-composer"><Composer {...{input,setInput,onKey,send,files,setFiles,fileRef,addFiles,inputRef,provider,ws,setModelMenu,setEffortMenu,modelMenu,effortMenu,fetching,refreshModels,t,rtl}}/></div></section>:<section className="home-view"><div className="greeting"><div className="greeting-orb"><span>BB</span><i className="orb-glow"/><i className="orb-satellite"/><i className="orb-spark"/></div><h1>{t('What should we work on?','روی چی کار کنیم؟')}</h1><p>{t('Your AI coding workspace, built for the long haul.','فضای کاری هوش مصنوعی برای ساختن چیزهای بزرگ.')}</p></div><div className="composer-wrap"><Composer {...{input,setInput,onKey,send,files,setFiles,fileRef,addFiles,inputRef,provider,ws,setModelMenu,setEffortMenu,modelMenu,effortMenu,fetching,refreshModels,t,rtl}}/><div className="home-hints"><span><ShieldCheck size={14}/>{ws.memory?t('Memory on','حافظه روشن'):t('Memory off','حافظه خاموش')}</span><span><Zap size={13}/>{ws.fullAccess?t('Full access','دسترسی کامل'):t('Ask before actions','پرسش پیش از اقدام')}</span><span><LockKeyhole size={13}/>{t('Private on this device','خصوصی روی این دستگاه')}</span></div></div>{sortedChats.length>0&&<div className="recent-cards"><div className="recent-card-heading">{t('Pick up where you left off','ادامه گفتگو')}</div><div className="recent-card-row">{sortedChats.slice(0,3).map(c=><button className="recent-card" key={c.id} onClick={()=>openChat(c.id)}><MessageCircle size={15}/><span>{c.title}</span><ChevronRight size={14}/></button>)}</div></div>}</section>}
      <footer className="footer"><span>{t('Br Ba Coding Agent can make mistakes. Verify important changes.','Br Ba Coding Agent ممکن است اشتباه کند. تغییرات مهم را بررسی کنید.')}</span><button onClick={()=>setSettings(true)}><CircleHelp size={13}/>{t('Help & settings','راهنما و تنظیمات')}</button></footer>
    </main>
    {settings&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setSettings(false);setNewProvider(false)}}}><div className="settings-modal settings-v2"><div className="modal-header"><div className="settings-heading"><div className="settings-heading-icon"><Settings2 size={18}/></div><div><div className="eyebrow">BR BA CODING AGENT · {t('PREFERENCES','تنظیمات')}</div><h2>{settingsNav.find(x=>x[0]===settingsTab)?.[2]}</h2></div></div><div className="settings-header-actions"><span className="settings-saved"><i/>{t('Saved locally','ذخیره محلی')}</span><button className="close-btn" onClick={()=>{setSettings(false);setNewProvider(false)}} aria-label="Close settings"><X size={18}/></button></div></div><div className="settings-layout"><nav className="settings-nav settings-nav-v2">{settingsNav.map(([id,Icon,label])=><button key={id} className={settingsTab===id?'current':''} onClick={()=>{setSettingsTab(id);setNewProvider(false)}}><Icon size={16}/><span>{label}</span>{id==='providers'&&ws.providers.length>0&&<small className="nav-count">{ws.providers.length}</small>}{id==='updates'&&<i className="nav-live-dot"/>}</button>)}<div className="settings-nav-bottom"><div className="mini-avatar">BB</div><span><b>Br Ba Workspace</b><small>v{appVersion}</small></span></div></nav><div className="settings-content settings-content-v2">{settingsContent}</div></div></div></div>}
    {projectModal&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setProjectModal(false)}}><div className="project-modal"><div className="modal-header"><div><div className="eyebrow">WORKSPACE</div><h2>{t('Create a project','ساخت پروژه')}</h2></div><button className="close-btn" onClick={()=>setProjectModal(false)}><X size={18}/></button></div><p>{t('Keep related chats together with their own context.','گفتگوهای مرتبط را با زمینه اختصاصی کنار هم نگه دارید.')}</p><label>{t('Project name','نام پروژه')}<input autoFocus value={projectName} onChange={e=>setProjectName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&addProject()} placeholder={t('e.g. Website redesign','مثلاً بازطراحی وب‌سایت')}/></label><div className="form-actions"><button className="outline small" onClick={()=>setProjectModal(false)}>{t('Cancel','لغو')}</button><button className="primary small" onClick={addProject} disabled={!projectName.trim()}><Plus size={14}/>{t('Create project','ساخت پروژه')}</button></div></div></div>}
    {toast&&<div className="toast"><Check size={15}/>{toast}</div>}
  </div>
}
function Composer(props:any){const {input,setInput,onKey,send,files,setFiles,fileRef,addFiles,inputRef,provider,ws,setModelMenu,setEffortMenu,modelMenu,effortMenu,fetching,refreshModels,t,rtl}=props;const [accessMenu,setAccessMenu]=useState(false);const currentProvider=ws.providers.find((p:Provider)=>p.id===ws.selectedProvider);const selectedModel=ws.selectedModel||t('Choose model','انتخاب مدل');const effort=ws.effort;const [dragging,setDragging]=useState(false);
return <div className={`composer ${dragging?'dragging':''}`} onDragOver={e=>{e.preventDefault();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);addFiles(e.dataTransfer.files)}}>
  {files.length>0&&<div className="file-chips">{files.map((f:any,i:number)=><div className="file-chip" key={i}>{f.type.startsWith('image/')?<img src={f.data}/>:<File size={15}/>}<span>{f.name}</span><button onClick={()=>setFiles(files.filter((_:any,n:number)=>n!==i))}><X size={13}/></button></div>)}</div>}
  <textarea ref={inputRef} value={input} onChange={e=>setInput(e.target.value)} onKeyDown={onKey} placeholder={t('Work with Br Ba Coding Agent','با Br Ba Coding Agent کار کنید')} rows={2}/>
  <div className="composer-controls"><div className="composer-left"><button className="round-tool" title={t('Attach files','پیوست فایل')} onClick={()=>fileRef.current?.click()}><Plus size={17}/></button><input ref={fileRef} type="file" multiple hidden onChange={e=>{addFiles(e.target.files);e.currentTarget.value=''}}/><div className="access-wrap"><button className={`access-trigger ${ws.fullAccess?'full':''}`} onClick={()=>setAccessMenu(!accessMenu)}><span className="access-dot"/>{ws.fullAccess?t('Full access','دسترسی کامل'):t('Ask before actions','پرسش پیش از اقدام')}<ChevronDown size={12}/></button>{accessMenu&&<div className="floating-menu access-menu"><button onClick={()=>{setAccessMenu(false);window.dispatchEvent(new CustomEvent('agent-access',{detail:false}))}}><ShieldCheck size={15}/><span><b>{t('Ask before actions','پرسش پیش از اقدام')}</b><small>{t('Safer for untrusted files','امن‌تر برای فایل‌های ناشناس')}</small></span></button><button onClick={()=>{setAccessMenu(false);window.dispatchEvent(new CustomEvent('agent-access',{detail:true}))}}><Zap size={15}/><span><b>{t('Full access','دسترسی کامل')}</b><small>{t('Preference only · no local tools yet','ترجیح کاربری · ابزار محلی هنوز ندارد')}</small></span></button></div>}</div></div>
    <div className="composer-right"><div className="model-wrap"><button className={`model-trigger ${modelMenu?'is-open':''}`} onClick={()=>setModelMenu(!modelMenu)}><span>{selectedModel}</span><ChevronDown size={13}/></button>{modelMenu&&<div className="floating-menu model-menu"><div className="menu-title">{t('Select a model','انتخاب مدل')}<button onClick={()=>refreshModels(currentProvider)} disabled={fetching}><ArrowDown size={13}/>{fetching?t('Fetching…','در حال دریافت…'):t('Refresh','تازه‌سازی')}</button></div>{ws.providers.length===0?<div className="menu-empty">{t('Add a provider in Settings first.','ابتدا ارائه‌دهنده را در تنظیمات اضافه کنید.')}</div>:ws.providers.map((p:Provider)=><div className="model-provider" key={p.id}><div className="model-provider-name">{p.name}<button onClick={()=>refreshModels(p)}><ArrowDown size={12}/></button></div>{(p.models.length?p.models:[]).map((m:string)=><button className={`model-option ${ws.selectedModel===m?'chosen':''}`} key={m} onClick={()=>{window.dispatchEvent(new CustomEvent('select-model',{detail:{provider:p.id,model:m}}));setModelMenu(false)}}><span>{m}</span>{ws.selectedModel===m&&<Check size={14}/>}</button>)}{!p.models.length&&<div className="menu-empty">{t('Fetch models to populate this list.','برای نمایش مدل‌ها دریافت را بزنید.')}</div>}</div>)}</div>}</div>
    <div className="effort-wrap"><button className="effort-trigger" onClick={()=>setEffortMenu(!effortMenu)}><span>{t('Effort','تلاش')} <b>{t(effort[0].toUpperCase()+effort.slice(1),({'low':'کم','medium':'متوسط','high':'زیاد'} as any)[effort])}</b></span><ChevronDown size={12}/></button>{effortMenu&&<div className="effort-pop"><div className="effort-pop-head"><div><b>{t('Reasoning effort','میزان تفکر')}</b><small>{selectedModel}</small></div><button onClick={()=>setEffortMenu(false)}><X size={14}/></button></div><div className="effort-values">{['low','medium','high'].map((x:string)=><button key={x} className={effort===x?'selected':''} onClick={()=>{window.dispatchEvent(new CustomEvent('set-effort',{detail:x}));setEffortMenu(false)}}>{t(x[0].toUpperCase()+x.slice(1),({'low':'کم','medium':'متوسط','high':'زیاد'} as any)[x])}</button>)}</div><div className="effort-track"><span className={`effort-thumb ${effort}`}/></div><p>{t('Controls how much reasoning the model uses.','میزان استدلالی را که مدل به‌کار می‌گیرد تنظیم می‌کند.')}</p></div>}</div>
    <button className="mic-button" title={t('Voice input (coming soon)','ورودی صوتی (به‌زودی)')} onClick={()=>window.dispatchEvent(new CustomEvent('toast',{detail:t('Voice input is coming soon.','ورودی صوتی به‌زودی اضافه می‌شود.')}))}><AudioLines size={16}/></button><button className={`send-button ${input.trim()||files.length?'ready':''}`} onClick={send} disabled={!input.trim()&&!files.length}><ArrowUp size={17}/></button></div>
  </div>{dragging&&<div className="drop-overlay"><UploadCloud size={25}/>{t('Drop files to attach','فایل را برای پیوست رها کنید')}</div>}</div>
}

createRoot(document.getElementById('root')!).render(<App/>);
